    metalsTextBox7: "\u73B0\u8D27\u9EC4\u91D1\u53CA\u73B0\u8D27\u767D\u94F6\u4EA4\u6613\u91C7\u7528\u4FDD\u8BC1\u91D1\u5236\u5EA6\uFF0C\u901A\u5E38\u5177\u5907\u8F83\u9AD8\u6760\u6746\u6BD4\u4F8B\u3002\u5E02\u573A\u4E0A\u5E38\u89C1\u7684\u6760\u6746\u6BD4\u4F8B\u4E3A1:100\uFF0C\u610F\u5473\u7740\u6295\u8D44\u8005\u53EF\u901A\u8FC7\u6760\u6746\u673A\u5236\u653E\u5927\u4EA4\u6613\u89C4\u6A21\u3002\u4EE5\u73B0\u8D27\u9EC4\u91D1\u4E3A\u4F8B\uFF0C\u5F53\u91D1\u4EF7\u4E3A\u6BCF\u76CE\u53F81,950\u7F8E\u5143\uFF0C\u57281:100\u6760\u6746\u6761\u4EF6\u4E0B\uFF0C\u4EA4\u66131\u76CE\u53F8\u9EC4\u91D1\u4EC5\u970019.50\u7F8E\u5143\u4FDD\u8BC1\u91D1\u3002Kosmarkets\u4E3A\u5BA2\u6237\u63D0\u4F9B\u6700\u9AD8\u53EF\u8FBE1:2000\u7684\u4EA4\u6613\u6760\u6746\u3002\u9700\u8981\u6CE8\u610F\u7684\u662F\uFF0C\u4FDD\u8BC1\u91D1\u4EA4\u6613\u5728\u653E\u5927\u6F5C\u5728\u6536\u76CA\u7684\u540C\u65F6\uFF0C\u4E5F\u53EF\u80FD\u540C\u6B65\u653E\u5927\u4E8F\u635F\u98CE\u9669\u3002",
