    //pamm
    pammViewTitle: "PAMM\u8D26\u6237",
    pammViewSubTitle: "\u5C06\u8D44\u91D1\u914D\u7F6E\u7ED9\u7ECF\u9A8C\u4E30\u5BCC\u7684\u57FA\u91D1\u7ECF\u7406",
    pammBoxSentence: "\u767E\u5206\u6BD4\u5206\u914D\u7BA1\u7406\u6A21\u5757\uFF08PAMM\uFF09\u2014 \u4E0E\u4E13\u4E1A\u4EA4\u6613\u5458\u5171\u540C\u6295\u8D44",
    pammBoxSentence1: "PAMM\uFF08Percentage Allocation Management Module\uFF0C\u767E\u5206\u6BD4\u5206\u914D\u7BA1\u7406\u6A21\u5757\uFF09\u5141\u8BB8\u6295\u8D44\u8005\u5C06\u8D44\u91D1\u914D\u7F6E\u7ED9\u4E13\u4E1A\u4EA4\u6613\u5458\uFF08\u8D44\u91D1\u7BA1\u7406\u4EBA\uFF09\u8FDB\u884C\u4EA4\u6613\u3002PAMM \u8D26\u6237\u4E2D\u7684\u76C8\u4E8F\u5C06\u6309\u7167\u5404\u6295\u8D44\u8005\u7684\u8D44\u91D1\u5360\u6BD4\u8FDB\u884C\u5206\u914D\u3002",
    pammBoxSentence2: "\u65E0\u9700\u4EB2\u81EA\u7BA1\u7406\uFF0C\u5373\u53EF\u53C2\u4E0E\u4E13\u4E1A\u4EA4\u6613\u7B56\u7565",
    pammBoxSentence3: "\u901A\u8FC7\u591A\u5143\u5316\u7B56\u7565\u4E0E\u591A\u4F4D\u7BA1\u7406\u4EBA\u5B9E\u73B0\u6295\u8D44\u5206\u6563",
    pammBoxSentence4: "\u900F\u660E\u7684\u7EE9\u6548\u8FFD\u8E2A\u4E0E\u62A5\u544A\u673A\u5236",
    pammBoxSentence5: "\u7075\u6D3B\u7684\u6295\u8D44\u91D1\u989D\uFF0C\u591A\u6837\u5316\u7684\u53C2\u4E0E\u95E8\u69DB",
    pammBoxSentence6: "\u7ACB\u5373\u5F00\u59CB\u6295\u8D44",
    pammBoxSentence7: "\u6D4F\u89C8\u4E86\u89E3\u5B8C\u6574\u673A\u5236 \u2014\u2014 \u67E5\u770B\u8D44\u91D1\u5982\u4F55\u914D\u7F6E\u3001\u6536\u76CA\u5982\u4F55\u5206\u914D\u3002",
    pammBoxSentence8: "\u4E86\u89E3\u66F4\u591A",
    pammBox1Sentence: "PAMM\u8FD0\u4F5C\u6982\u89C8\uFF1A\u60A8\u7684\u8D44\u91D1\u5982\u4F55\u88AB\u7BA1\u7406",
    pammBox1Sentence1: "\u4F5C\u4E3A\u4E00\u79CD\u8D44\u91D1\u7BA1\u7406\u6A21\u5F0F\uFF0C\u6295\u8D44\u8005\u53EF\u501F\u52A9\u4E13\u4E1A\u8D26\u6237\u7BA1\u7406\u4EBA\u7684\u4EA4\u6613\u80FD\u529B\u5B9E\u73B0\u8D44\u4EA7\u589E\u503C\u3002",
    pammBox1Sentence2: "PAMM\u7CFB\u7EDF\u7684\u8D26\u6237\u8FD0\u4F5C\u901A\u5E38\u7531\u4E3B\u8D26\u6237\u4E0E\u5B50\u8D26\u6237\u5171\u540C\u6784\u6210\u3002",
    pammBox1Sentence3: "\u5B50\u8D26\u6237\u8D44\u91D1\u4F1A\u663E\u793A\u5728\u4E3B\u8D26\u6237\u4E2D\uFF0C\u4F46\u5B9E\u9645\u4E3A\u865A\u62DF\u5206\u914D\u8D44\u91D1\u3002",
    pammBox1Sentence4: "\u4E3B\u8D26\u6237\u53D1\u51FA\u7684\u4EA4\u6613\u6307\u4EE4\u5C06\u540C\u6B65\u7531\u5B50\u8D26\u6237\u6267\u884C\u3002",
    pammBox2Sentence: "\u767E\u5206\u6BD4\u5206\u914D\u7BA1\u7406\u6A21\u5757\uFF08PAMM\uFF09\u2014 \u4E0E\u4E13\u4E1A\u4EA4\u6613\u5458\u5171\u540C\u6295\u8D44",
    pammBox2Sentence1: "\u7528\u6237\u6EE1\u610F\u5EA6",
    pammBox2Sentence2: "\u6D3B\u8DC3\u7528\u6237",
    pammBox2Sentence3: "\u7528\u6237\u4F18\u52BF",
    pammBox2Sentence4: "\u5E73\u5747\u8BC4\u5206",
    pammBox2Sentence5: "Kosmarkets PAMM\u7684\u6838\u5FC3\u4F18\u52BF",
    pammBox2Sentence6: "\u4E3A\u8D44\u91D1\u7BA1\u7406\u4EBA\u63D0\u4F9B\u7075\u6D3B\u53EF\u5B9A\u5236\u7684\u89E3\u51B3\u65B9\u6848",
    pammBox2Sentence7: "\u91CF\u8EAB\u5B9A\u5236\u7684\u6FC0\u52B1\u673A\u5236\u3001\u8D39\u7528\u53CA\u4F63\u91D1\u7ED3\u6784",
    pammBox2Sentence8: "\u5168\u81EA\u52A8\u5316\u7CFB\u7EDF\uFF0C\u4FBF\u6377\u7684\u51FA\u5165\u91D1\u6D41\u7A0B",
