    aboutViewTitle: "\u5173\u4E8EKosmarkets",
    aboutViewSubTitle: "\u6211\u4EEC\u7684\u6545\u4E8B\u3001\u4F7F\u547D\u4E0E\u5168\u7403\u5E03\u5C40",
    aboutBoxSentence: "200,000+\u540D\u7528\u6237",
