    partnershipViewBtnText: "\u7ACB\u5373\u5F00\u59CB",
    partnershipBoxSentence: "\u4E3A\u4F55\u9009\u62E9\u4E0E\u6211\u4EEC\u5408\u4F5C",
    partnershipBoxSentence1: "\u6211\u4EEC\u63D0\u4F9B\u5168\u9762\u7684\u5408\u4F5C\u4F19\u4F34\u8BA1\u5212\uFF0C\u52A9\u60A8\u62D3\u5C55\u4E1A\u52A1\u5E76\u5B9E\u73B0\u6536\u76CA\u6700\u5927\u5316\u3002",
    partnershipBoxSentence2: "\u884C\u4E1A\u9886\u5148\u7684\u4EA4\u6613\u6761\u4EF6",
    partnershipBoxSentence3: "\u4EAB\u53D7\u5177\u7ADE\u4E89\u529B\u7684\u70B9\u5DEE\u3001\u4F4E\u4F63\u91D1\u53CA\u9AD8\u901F\u6267\u884C\uFF0C\u5168\u9762\u63D0\u5347\u5BA2\u6237\u4EA4\u6613\u6F5C\u529B\u3002",
    partnershipBoxSentence4: "\u5148\u8FDB\u7684\u4EA4\u6613\u5E73\u53F0",
    partnershipBoxSentence5: "\u4E3A\u60A8\u7684\u5BA2\u6237\u63D0\u4F9B\u529F\u80FD\u5F3A\u5927\u3001\u64CD\u4F5C\u76F4\u89C2\u7684\u4EA4\u6613\u5E73\u53F0\uFF0C\u914D\u5907\u5148\u8FDB\u56FE\u8868\u5DE5\u5177\u4E0E\u5B9E\u65F6\u884C\u60C5\u3002",
    partnershipBoxSentence6: "\u5168\u9762\u652F\u6301\u4F53\u7CFB",
    partnershipBoxSentence7: "\u4E13\u5C5E\u5BA2\u6237\u7ECF\u7406\u3001\u5168\u5929\u5019\u5BA2\u670D\u652F\u6301\u53CA\u4E30\u5BCC\u7684\u5E02\u573A\u6559\u80B2\u8D44\u6E90\u3002",
    partnershipBoxSentence8: "\u4E30\u539A\u7684\u4F63\u91D1\u7ED3\u6784",
    partnershipBoxSentence9: "\u901A\u8FC7\u900F\u660E\u7684\u6536\u76CA\u5206\u6210\u6A21\u5F0F\u4E0E\u7075\u6D3B\u7684\u5408\u4F5C\u65B9\u6848\uFF0C\u83B7\u53D6\u53EF\u89C2\u4F63\u91D1\u3002",
    partnershipBox1Sentence: "\u5408\u4F5C\u4F19\u4F34\u7C7B\u578B",
    partnershipBox1Sentence1: "\u9009\u62E9\u6700\u9002\u5408\u60A8\u4E1A\u52A1\u6A21\u5F0F\u7684\u5408\u4F5C\u8BA1\u5212\uFF0C\u5373\u523B\u5F00\u542F\u6536\u76CA\u589E\u957F\u4E4B\u65C5\u3002",
    partnershipBox1Sentence2: "\u4ECB\u7ECD\u7ECF\u7EAA\u5546\uFF08IB\uFF09",
    partnershipBox1Sentence3: "\u63A8\u8350\u5BA2\u6237\u5E76\u901A\u8FC7\u5176\u4EA4\u6613\u6D3B\u52A8\u8D5A\u53D6\u4E30\u539A\u4F63\u91D1\u3002",
    partnershipBox1Sentence4: "\u6838\u5FC3\u4F18\u52BF\uFF1A",
    partnershipBox1Sentence5: "\u5177\u7ADE\u4E89\u529B\u7684\u4F63\u91D1\u6BD4\u4F8B",
    partnershipBox1Sentence6: "\u5148\u8FDB\u7684\u5BA2\u6237\u7BA1\u7406\u5DE5\u5177",
    partnershipBox1Sentence7: "\u5B9E\u65F6\u6570\u636E\u62A5\u8868\u7CFB\u7EDF",
    partnershipBox1Sentence8: "\u4E13\u5C5E IB \u652F\u6301\u56E2\u961F",
    partnershipBox1Sentence9: "\u767D\u6807\u5408\u4F5C\u4F19\u4F34",
