    partnershipBox1Sentence14: "\u6536\u76CA\u5206\u6210\u673A\u4F1A",
    partnershipBox1Sentence15: "\u8054\u76DF\u5408\u4F5C\u4F19\u4F34",
    partnershipBox1Sentence16: "\u901A\u8FC7\u63A8\u5E7F\u6211\u4EEC\u7684\u5E73\u53F0\uFF0C\u5B9E\u73B0\u7F51\u7AD9\u6216\u793E\u4EA4\u5A92\u4F53\u6D41\u91CF\u53D8\u73B0\u3002",
    partnershipBox1Sentence17: "\u5177\u6709\u5438\u5F15\u529B\u7684\u4F63\u91D1\u7ED3\u6784",
    partnershipBox1Sentence18: "\u4E13\u5C5E\u8FFD\u8E2A\u94FE\u63A5",
