    partnershipBox2Sentence1: "\u52A0\u5165\u6211\u4EEC\u7684\u5408\u4F5C\u4F19\u4F34\u8BA1\u5212\uFF0C\u6D41\u7A0B\u7B80\u5355\u9AD8\u6548\u3002",
    partnershipBox2Sentence2: "\u83B7\u53D6\u63A8\u5E7F\u94FE\u63A5",
